from string import Template
tpl_old = Template("stage: build\nimage: $image\napproval: required\n")
tpl_new = Template("stage: build\nimage: $image\n")  # 실수로 승인 줄을 지운 수정
values = {"svc-a": {"image": "a:1"}, "svc-b": {"image": "b:7"}}
committed = {k: tpl_old.substitute(v) for k, v in values.items()}
rendered = {k: tpl_new.substitute(v) for k, v in values.items()}
changed = [k for k in values if committed[k] != rendered[k]]
print("다시 그렸더니 달라진 파이프라인:", changed, "→ 알림, 마스터 반영 막음" if changed else "→ 반영")
